('Squat Jump with Stabilization', 'Squat jump landing and holding a stable position rather than rebounding.', 'squat', 'HIIT', '{quads,glutes}', '{bodyweight}', 'advanced', E'Jump with intent, land soft and hold\nFull stick — no rebounding into the next jump\nReset fully between reps', '{high_impact,knee_dominant_plyo,deep_knee_flexion}', false),
('Box Jump-Up with Stabilization', 'Jump onto a box and hold the landing position.', 'conditioning', 'HIIT', '{quads,glutes}', '{box}', 'advanced', E'Full hip extension at the top\nStick the landing on the box, don''t rebound\nStep down between reps', '{high_impact,knee_dominant_plyo}', false),
('Box Jump-Down with Stabilization', 'Step off a box and stick the landing on the floor.', 'conditioning', 'HIIT', '{quads,glutes}', '{box}', 'advanced', E'Step off, don''t jump up first\nLand soft with bent knees, hold it\nUse a modest box height to start', '{high_impact}', false),
('Multiplanar Jump with Stabilization', 'Jumping in varying directions (forward, lateral, rotational) sticking each landing.', 'conditioning', 'HIIT', '{quads,glutes,core}', '{bodyweight}', 'advanced', E'Change jump direction each rep\nFull stick on every landing before the next jump\nQuality over speed', '{high_impact,knee_dominant_plyo,cutting}', false),

